/** Colour family of a book's icon box. */
enum class BookFamily { Wiki, Maps, Aid, Books, Games, Travel }

@Immutable
data class BookTone(val background: Color, val foreground: Color)

fun bookTone(family: BookFamily, dark: Boolean): BookTone = when (family) {
    BookFamily.Wiki -> if (dark) BookTone(Color(0xFF2A3A2F), Color(0xFFE9DFC8)) else BookTone(Color(0xFFE9DFC8), Color(0xFF1F3D2F))
    BookFamily.Maps -> if (dark) BookTone(Color(0xFF22392B), Color(0xFFB5CFA2)) else BookTone(Color(0xFFDCE6D3), Color(0xFF2F5642))
    BookFamily.Aid -> if (dark) BookTone(Color(0xFF3B211B), Color(0xFFF0A08F)) else BookTone(Color(0xFFF6D8CE), Color(0xFFB4321F))
    BookFamily.Books -> if (dark) BookTone(Color(0xFF33291A), Color(0xFFE3C08E)) else BookTone(Color(0xFFEFDDBF), Color(0xFF7A4B12))
    BookFamily.Games -> if (dark) BookTone(Color(0xFF3A2416), Color(0xFFFFB98C)) else BookTone(Color(0xFFFBDCC8), Color(0xFFA33F05))
    BookFamily.Travel -> if (dark) BookTone(Color(0xFF20322C), Color(0xFFA9C7BC)) else BookTone(Color(0xFFD8E2DA), Color(0xFF3E5F55))
}
